<?php require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/ui.php';requireProfile($conn);$q=trim($_GET['q']??'');$type=$_GET['type']??'ALL';$cat=(int)($_GET['category_id']??0);$loc=(int)($_GET['location_id']??0);$date=trim($_GET['date']??'');$categories=$conn->query('SELECT id,name FROM categories ORDER BY name');$locations=$conn->query('SELECT id,name FROM locations ORDER BY name');$where="r.status='VERIFIED'";$params=[];$types='';if(in_array($type,['LOST','FOUND'])){$where.=' AND r.type=?';$types.='s';$params[]=$type;}if($q!==''){$where.=' AND (r.item_name LIKE ? OR r.description LIKE ?)';$types.='ss';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if($cat>0){$where.=' AND r.category_id=?';$types.='i';$params[]=$cat;}if($loc>0){$where.=' AND r.location_id=?';$types.='i';$params[]=$loc;}if($date!==''){$where.=' AND r.incident_date=?';$types.='s';$params[]=$date;}$sql="SELECT r.id,r.type,r.item_name,r.image,r.incident_date,r.status,c.name category_name,l.name location_name,u.name reporter_name FROM reports r LEFT JOIN categories c ON c.id=r.category_id LEFT JOIN locations l ON l.id=r.location_id JOIN users u ON u.id=r.user_id WHERE $where ORDER BY r.created_at DESC LIMIT 100";$st=$conn->prepare($sql);if($params)$st->bind_param($types,...$params);$st->execute();$rows=$st->get_result();$titleForTop='Cari Barang';renderHead('Cari Barang');renderUserNav('search');?><div class="content animate-in"><div class="section-head"><div><h1 class="hero-title">Cari Barang</h1><p class="muted">Cari laporan barang hilang maupun ditemukan berdasarkan nama, kategori, lokasi, dan tanggal.</p></div><a class="btn btn-primary" href="matching.php">✦ Smart Matching</a></div><form class="card searchbar" method="get"><input class="form-control wide" name="q" value="<?= e($q) ?>" placeholder="Cari nama barang atau kata kunci deskripsi..."><select class="form-select" name="type"><option value="ALL">Semua</option><option value="LOST" <?= $type==='LOST'?'selected':'' ?>>Barang Hilang</option><option value="FOUND" <?= $type==='FOUND'?'selected':'' ?>>Barang Ditemukan</option></select><select class="form-select" name="category_id"><option value="0">Semua Kategori</option><?php while($c=$categories->fetch_assoc()): ?><option value="<?= $c['id'] ?>" <?= $cat===$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endwhile; ?></select><select class="form-select" name="location_id"><option value="0">Semua Lokasi</option><?php while($l=$locations->fetch_assoc()): ?><option value="<?= $l['id'] ?>" <?= $loc===$l['id']?'selected':'' ?>><?= e($l['name']) ?></option><?php endwhile; ?></select><button class="btn btn-blue" type="submit">Cari</button><input class="form-control" type="date" name="date" value="<?= e($date) ?>" style="grid-column:1/-1"></form><div class="section"><div class="section-head"><h2><?= $rows->num_rows ?> hasil terverifikasi</h2></div><div class="grid grid-3 stagger"><?php if($rows->num_rows): while($r=$rows->fetch_assoc()): ?><a class="card item-card" href="detail-barang.php?id=<?= $r['id'] ?>"><div class="thumb"><?php if($r['image']): ?><img src="uploads/<?= e($r['image']) ?>" alt=""><?php else: ?>📦<?php endif; ?></div><div class="body"><span class="pill <?= $r['type']==='FOUND'?'pill-green':'pill-red' ?>"><?= $r['type']==='FOUND'?'Ditemukan':'Hilang' ?></span><h3><?= e($r['item_name']) ?></h3><div class="meta">📍 <?= e($r['location_name']??'-') ?><br>📅 <?= e($r['incident_date']) ?><br>👤 <?= e($r['reporter_name']) ?></div></div></a><?php endwhile;else: ?><div class="empty" style="grid-column:1/-1">Tidak ada barang yang cocok dengan pencarianmu.</div><?php endif; ?></div></div></div><?php renderFooter(); ?>
